curl -sL "https://cdn.jsdelivr.net/npm/p5@2.3.1/types/global.d.ts" -o global.d.ts && \
node -e '
const fs = require("fs");
let p5 = fs.readFileSync("p5.d.ts","utf8");
let g = fs.readFileSync("global.d.ts","utf8");
p5 = p5.replace(/^\/\/ This file is auto-generated from JSDoc documentation\n?/, "")
  .replace(/export\s+default\s+p5\s*;\s*$/m, "")
  .replace(/export\s+as\s+namespace\s+p5\s*;\s*$/m, "");
g = g.replace(/^\/\/ This file is auto-generated from JSDoc documentation\n?/, "")
  .replace(/import\s+P5\s+from\s+['\''"]\.\/p5['\''"]\s*;\s*/, "")
  .replace(/typeof\s+P5\.([a-zA-Z_]\w*)/g, "typeof $1")
  .replace(/(?<=:\s*)P5(?=\s*[;|\n])/g, "p5");
// strip trailing export default from global if any
g = g.replace(/export\s+default\s+p5\s*;\s*$/m, "");
const out = `// Generated p5.js Type Definitions
// Bundled from p5.js v2.3.1 official type definitions
// Generated: ${new Date().toISOString()}

${p5}

${g}

export as namespace p5;
export = p5;
`;
fs.writeFileSync("bundled.d.ts", out);
console.log("size", fs.statSync("bundled.d.ts").size);
